function check([words, groups], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== expected.length) return false;
  const position = new Map(words.map((word, i) => [word, i]));
  let previous = -1;
  for (const word of actual) {
    const index = position.get(word);
    if (index === undefined || index <= previous) return false;
    if (previous >= 0 && groups[index] === groups[previous]) return false;
    previous = index;
  }
  return true;
}

