function validate([words, groups]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  if (!Array.isArray(groups) || groups.length !== words.length) return 'groups must be as long as words.';
  if (!groups.every(g => g === 0 || g === 1)) return 'Each groups[i] is 0 or 1.';
  if (!words.every(w => typeof w === 'string' && /^[a-z]{1,10}$/.test(w))) return 'Each word has 1 to 10 lowercase letters.';
  if (new Set(words).size !== words.length) return 'The words must all be different.';
  return null;
}

