function getLongestSubsequence(words, groups) {
  const n = words.length;
  const best = new Array(n).fill(1);
  const parent = new Array(n).fill(-1);
  for (let i = 0; i < n; i++)
    for (let j = 0; j < i; j++)
      if (groups[j] !== groups[i] && best[j] + 1 > best[i]) { best[i] = best[j] + 1; parent[i] = j; }
  let end = 0;
  for (let i = 1; i < n; i++) if (best[i] > best[end]) end = i;
  const picked = [];
  for (let i = end; i !== -1; i = parent[i]) picked.push(words[i]);
  return picked.reverse();
}

