function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const letters = size === 'large' ? 26 : 4;
  const seen = new Set();
  const words = [];
  while (words.length < n) {
    const length = 1 + Math.floor(rand() * (size === 'large' ? 10 : 3));
    let word = '';
    for (let k = 0; k < length; k++) word += String.fromCharCode(97 + Math.floor(rand() * letters));
    if (!seen.has(word)) { seen.add(word); words.push(word); }
  }
  const stay = rand();
  const groups = [];
  for (let i = 0; i < n; i++) groups.push(i > 0 && rand() < stay ? groups[i - 1] : Math.floor(rand() * 2));
  return [words, groups];
}
